{
    "classes": [
        {
            "doc": "\nTransient cylinder. A transient cylinder is not displayed or saved in a document.\nA transient cylinder is but is used as a wrapper to work with raw cylinder information.\nA transient cylinder has no boundaries and is infinite in length.\nThey are created statically using the create method of the Cylinder class.\n",
            "functions": [
                {
                    "doc": "Gets the data that defines the cylinder",
                    "name": "getData"
                },
                {
                    "doc": "Sets the data that defines the cylinder",
                    "name": "set"
                },
                {
                    "doc": "Creates and returns an independent copy of this Cylinder object",
                    "name": "copy"
                },
                {
                    "doc": "Updates this surface by transforming it with a given input matrix",
                    "name": "transformBy"
                }
            ],
            "name": "Cylinder",
            "namespace": "adsk.core",
            "properties": [
                {
                    "doc": "The origin point (center) of the base of the cylinder",
                    "name": "origin"
                },
                {
                    "doc": "The center axis (along the length) of the cylinder that defines its normal direction",
                    "name": "axis"
                },
                {
                    "doc": "The radius of the cylinder",
                    "name": "radius"
                }
            ],
            "staticmethods": [
                {
                    "doc": "Creates a transient cylinder object",
                    "name": "create"
                }
            ],
            "type": "class"
        },
        {
            "doc": "\nTransient plane. A transient plane is not displayed or saved in a document.\nTransient planes are used as a wrapper to work with raw plane information.\nA transient plane has no boundaries or size, but is infinite and is represented\nby a position, a normal, and an orientation in space.\nThey are created statically using the create method of the Plane class.\n",
            "functions": [
                {
                    "doc": "Sets the U and V directions of the plane",
                    "name": "setUVDirections"
                },
                {
                    "doc": "Checks if this plane is parallel to another plane",
                    "name": "isParallelToPlane"
                },
                {
                    "doc": "Checks if this plane is parallel to a line",
                    "name": "isParallelToLine"
                },
                {
                    "doc": "Checks if this plane is perpendicular to another plane",
                    "name": "isPerpendicularToPlane"
                },
                {
                    "doc": "Checks if this plane is perpendicular to a line",
                    "name": "isPerpendicularToLine"
                },
                {
                    "doc": "Checks if this plane is coplanar with another plane",
                    "name": "isCoPlanarTo"
                },
                {
                    "doc": "Creates an infinite line at the intersection of this plane with another plane",
                    "name": "intersectWithPlane"
                },
                {
                    "doc": "Creates a 3D point at the intersection of this plane and a line",
                    "name": "intersectWithLine"
                },
                {
                    "doc": "Intersect this plane with a curve to get the intersection point(s)",
                    "name": "intersectWithCurve"
                },
                {
                    "doc": "Intersect this plane with a surface to get the intersection point(s)",
                    "name": "intersectWithSurface"
                },
                {
                    "doc": "Creates and returns an independent copy of this Plane object",
                    "name": "copy"
                },
                {
                    "doc": "Updates this surface by transforming it with a given input matrix",
                    "name": "transformBy"
                }
            ],
            "name": "Plane",
            "namespace": "adsk.core",
            "properties": [
                {
                    "doc": "Gets and sets the origin point of the plane",
                    "name": "origin"
                },
                {
                    "doc": "Gets and sets the normal of the plane",
                    "name": "normal"
                },
                {
                    "doc": "Gets the U Direction of the plane",
                    "name": "uDirection"
                },
                {
                    "doc": "Gets the V Direction of the plane",
                    "name": "vDirection"
                }
            ],
            "staticmethods": [
                {
                    "doc": "Creates a transient plane object by specifying an origin and a normal direction",
                    "name": "create"
                },
                {
                    "doc": "Creates a transient plane object by specifying an origin along with U and V directions",
                    "name": "createUsingDirections"
                }
            ],
            "type": "class"
        }
    ],
